var minTimeForKComponents = function(n, edges, k) {
    if (n <= k) return 0;
    const sortedEdges = edges.slice().sort((a, b) => a[2] - b[2]);

    const parent = new Int32Array(n);
    for (let i = 0; i < n; i++) parent[i] = i;

    const find = (x) => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };

    const union = (x, y) => {
        const rx = find(x), ry = find(y);
        if (rx !== ry) {
            parent[rx] = ry;
            return true;
        }
        return false;
    };

    let comps = n;
    for (const [u, v, t] of sortedEdges) {
        if (union(u, v)) {
            comps--;
            if (comps <= k) return t;
        }
    }

    return -1;
};
